INSERT INTO `categoria` (`idCategoria`, `nombre`, `descripcion`) VALUES
(1, 'Mitología Griega', 'Criaturas y monstruos de los mitos de la antigua Grecia.'),
(2, 'Mitología Nórdica', 'Entidades primordiales y bestias de las sagas escandinavas.'),
(3, 'Folclore Japonés', 'Yokai, espíritus y criaturas legendarias del archipiélago nipón.'),
(4, 'Mitología Mesoamericana', 'Seres sagrados y monstruos de las culturas azteca, maya y regionales.'),
(5, 'Bestias Mágicas', 'Criaturas legendarias con propiedades sobrenaturales o elementales.'),
(6, 'Dragones y Reptiles', 'Sierpes colosales, wyverns y reptiles alados de diversas tradiciones.'),
(7, 'Folclore Celta y Europeo', 'Bestias feéricas, espectrales y monstruos del folclore europeo.'),
(8, 'Criptozoología', 'Entidades contemporáneas no clasificadas con avistamientos modernos.');
