INSERT INTO `caracteristica` (`descripcion`, `idHabitat`) VALUES
('Humedales sulfurosos cubiertos de niebla densa y aguas estancadas.', 1),
('Laderas rocosas con fisuras volcánicas y emisiones naturales de gas.', 2),
('Acantilados de basalto negro azotados por vientos marinos constantes.', 3),
('Valles montañosos de robledales espesos y praderas de altura.', 4),
('Grutas lávicas profundas con acústica cavernosa y olor a azufre.', 5),
('Islotes escarpados con corrientes ascendentes violentas.', 6),
('Corrientes submarinas traicioneras entre arrecifes afilados.', 7),
('Dunas calcinadas y ruinas de piedra caliza enterradas bajo arena.', 8),
('Cañones áridos de roca rojiza y temperaturas extremas.', 9),
('Fosas oceánicas gélidas con corrientes abisales de alta presión.', 10),
('Taiga boreal impenetrable con árboles retorcidos y hielo perpetuo.', 11),
('Glaciares milenarios y acantilados de granito sumergidos en bruma.', 12),
('Subsuelo geotérmico de cavernas heladas y ríos subterráneos.', 13),
('Bosques de cedros centenarios envueltos en neblina matinal.', 14),
('Afluentes fríos de montaña con pozas profundas y cañaverales.', 15),
('Gargantas fluviales húmedas con múltiples cascadas ocultas.', 16),
('Selva tropical densa con cenotes profundos y ruinas cubiertas de musgo.', 17),
('Cadenas montañosas áridas con cuevas de piedra caliza.', 18),
('Canales pantanosos oscuros rodeados de vegetación palustre.', 19),
('Barrancos secos, salinas y oquedades rocosas bajo sol implacable.', 20),
('Picos boscosos brumosos con pasos montañosos aislados.', 21),
('Lagos profundos de aguas turbias y turberas frías.', 22),
('Acantilados atlánticos batidos por tormentas y bancos de niebla.', 23),
('Bosques subárticos de coníferas con inviernos prolongados.', 24),
('Nieves perpetuas sobre los 5000 metros con ventiscas constantes.', 25),
('Zona fluvial boscosa con complejos industriales abandonados.', 26);
