INSERT INTO `registro` (`nroRegistro`, `fechaAprobacion`, `fechaBaja`, `idUsuario`, `estado`, `idBestia`, `main_picture`, `introduccion`, `historia`, `descripcion`, `resumen`) VALUES
(1, '2022-01-01 00:00:00', NULL, 1, 'aprobado', 1, 'bestiario_seed/beast_01', '[Edición 2022 - Revisión Historiográfica Inicial] El expediente dedicado a Hidra de Lerna (clasificación de peligrosidad: Alta) aborda en esta etapa la recopilación de crónicas antiguas y manuscritos regionales. Caracterizada por presentar múltiples cabezas regenerativas y aliento tóxico, esta entidad ha sido vinculada de forma recurrente con pantanos sulfurosos del Peloponeso. El presente registro documenta los avances obtenidos durante el ciclo anual 2022 para consolidar su ficha técnica dentro del Bestiario.', 'Durante la campaña de investigación correspondiente al año 2022, el equipo asignado al seguimiento de Hidra de Lerna centró sus esfuerzos en la recopilación de crónicas antiguas y manuscritos regionales. Las referencias documentales recolectadas en pantanos sulfurosos del Peloponeso permitieron contrastar relatos históricos previos con nuevos indicios verificados en terreno, destacando episodios de actividad estacional relacionados con su múltiples cabezas regenerativas y aliento tóxico. Cada hallazgo fue auditado y fechado el 2022-01-01 para preservar la trazabilidad evolutiva del caso.', 'Desde el punto de vista descriptivo (revisión 2022), Hidra de Lerna exhibe como rasgo diagnóstico principal múltiples cabezas regenerativas y aliento tóxico. Su nivel de amenaza (Alta) exige mantener distancia de seguridad en las inmediaciones de pantanos sulfurosos del Peloponeso, especialmente cuando las condiciones ambientales favorecen su desplazamiento. Las mediciones de la fase ''Revisión Historiográfica Inicial'' confirman patrones de comportamiento consistentes con las observaciones acumuladas desde el inicio del archivo.', 'Síntesis 2022 de Hidra de Lerna: peligro Alta, hábitat principal en pantanos sulfurosos del Peloponeso y rasgo clave ''múltiples cabezas regenerativas y aliento tóxico''. Registro 1/5 correspondiente a la fase ''Revisión Historiográfica Inicial'', validado para consulta histórica y comparativa.'),
(2, '2023-01-01 00:00:00', NULL, 2, 'aprobado', 1, 'bestiario_seed/beast_01', '[Edición 2023 - Prospección Geográfica de Campo] El expediente dedicado a Hidra de Lerna (clasificación de peligrosidad: Alta) aborda en esta etapa el rastreo topográfico y mapeo satelital de su entorno natural. Caracterizada por presentar múltiples cabezas regenerativas y aliento tóxico, esta entidad ha sido vinculada de forma recurrente con pantanos sulfurosos del Peloponeso. El presente registro documenta los avances obtenidos durante el ciclo anual 2023 para consolidar su ficha técnica dentro del Bestiario.', 'Durante la campaña de investigación correspondiente al año 2023, el equipo asignado al seguimiento de Hidra de Lerna centró sus esfuerzos en el rastreo topográfico y mapeo satelital de su entorno natural. Las referencias documentales recolectadas en pantanos sulfurosos del Peloponeso permitieron contrastar relatos históricos previos con nuevos indicios verificados en terreno, destacando episodios de actividad estacional relacionados con su múltiples cabezas regenerativas y aliento tóxico. Cada hallazgo fue auditado y fechado el 2023-01-01 para preservar la trazabilidad evolutiva del caso.', 'Desde el punto de vista descriptivo (revisión 2023), Hidra de Lerna exhibe como rasgo diagnóstico principal múltiples cabezas regenerativas y aliento tóxico. Su nivel de amenaza (Alta) exige mantener distancia de seguridad en las inmediaciones de pantanos sulfurosos del Peloponeso, especialmente cuando las condiciones ambientales favorecen su desplazamiento. Las mediciones de la fase ''Prospección Geográfica de Campo'' confirman patrones de comportamiento consistentes con las observaciones acumuladas desde el inicio del archivo.', 'Síntesis 2023 de Hidra de Lerna: peligro Alta, hábitat principal en pantanos sulfurosos del Peloponeso y rasgo clave ''múltiples cabezas regenerativas y aliento tóxico''. Registro 2/5 correspondiente a la fase ''Prospección Geográfica de Campo'', validado para consulta histórica y comparativa.'),
(3, '2024-01-01 00:00:00', NULL, 4, 'aprobado', 1, 'bestiario_seed/beast_01', '[Edición 2024 - Evaluación Morfológica y Anatómica] El expediente dedicado a Hidra de Lerna (clasificación de peligrosidad: Alta) aborda en esta etapa el estudio biomecánico de huellas, restos y testimonios visuales. Caracterizada por presentar múltiples cabezas regenerativas y aliento tóxico, esta entidad ha sido vinculada de forma recurrente con pantanos sulfurosos del Peloponeso. El presente registro documenta los avances obtenidos durante el ciclo anual 2024 para consolidar su ficha técnica dentro del Bestiario.', 'Durante la campaña de investigación correspondiente al año 2024, el equipo asignado al seguimiento de Hidra de Lerna centró sus esfuerzos en el estudio biomecánico de huellas, restos y testimonios visuales. Las referencias documentales recolectadas en pantanos sulfurosos del Peloponeso permitieron contrastar relatos históricos previos con nuevos indicios verificados en terreno, destacando episodios de actividad estacional relacionados con su múltiples cabezas regenerativas y aliento tóxico. Cada hallazgo fue auditado y fechado el 2024-01-01 para preservar la trazabilidad evolutiva del caso.', 'Desde el punto de vista descriptivo (revisión 2024), Hidra de Lerna exhibe como rasgo diagnóstico principal múltiples cabezas regenerativas y aliento tóxico. Su nivel de amenaza (Alta) exige mantener distancia de seguridad en las inmediaciones de pantanos sulfurosos del Peloponeso, especialmente cuando las condiciones ambientales favorecen su desplazamiento. Las mediciones de la fase ''Evaluación Morfológica y Anatómica'' confirman patrones de comportamiento consistentes con las observaciones acumuladas desde el inicio del archivo.', 'Síntesis 2024 de Hidra de Lerna: peligro Alta, hábitat principal en pantanos sulfurosos del Peloponeso y rasgo clave ''múltiples cabezas regenerativas y aliento tóxico''. Registro 3/5 correspondiente a la fase ''Evaluación Morfológica y Anatómica'', validado para consulta histórica y comparativa.'),
(4, '2025-01-01 00:00:00', NULL, 1, 'aprobado', 1, 'bestiario_seed/beast_01', '[Edición 2025 - Análisis Bioacústico y Forense] El expediente dedicado a Hidra de Lerna (clasificación de peligrosidad: Alta) aborda en esta etapa el procesamiento de registros sonoros, muestras biológicas y sensores remotos. Caracterizada por presentar múltiples cabezas regenerativas y aliento tóxico, esta entidad ha sido vinculada de forma recurrente con pantanos sulfurosos del Peloponeso. El presente registro documenta los avances obtenidos durante el ciclo anual 2025 para consolidar su ficha técnica dentro del Bestiario.', 'Durante la campaña de investigación correspondiente al año 2025, el equipo asignado al seguimiento de Hidra de Lerna centró sus esfuerzos en el procesamiento de registros sonoros, muestras biológicas y sensores remotos. Las referencias documentales recolectadas en pantanos sulfurosos del Peloponeso permitieron contrastar relatos históricos previos con nuevos indicios verificados en terreno, destacando episodios de actividad estacional relacionados con su múltiples cabezas regenerativas y aliento tóxico. Cada hallazgo fue auditado y fechado el 2025-01-01 para preservar la trazabilidad evolutiva del caso.', 'Desde el punto de vista descriptivo (revisión 2025), Hidra de Lerna exhibe como rasgo diagnóstico principal múltiples cabezas regenerativas y aliento tóxico. Su nivel de amenaza (Alta) exige mantener distancia de seguridad en las inmediaciones de pantanos sulfurosos del Peloponeso, especialmente cuando las condiciones ambientales favorecen su desplazamiento. Las mediciones de la fase ''Análisis Bioacústico y Forense'' confirman patrones de comportamiento consistentes con las observaciones acumuladas desde el inicio del archivo.', 'Síntesis 2025 de Hidra de Lerna: peligro Alta, hábitat principal en pantanos sulfurosos del Peloponeso y rasgo clave ''múltiples cabezas regenerativas y aliento tóxico''. Registro 4/5 correspondiente a la fase ''Análisis Bioacústico y Forense'', validado para consulta histórica y comparativa.'),
(5, '2026-01-01 00:00:00', NULL, 2, 'aprobado', 1, 'bestiario_seed/beast_01', '[Edición 2026 - Protocolo Actual de Monitoreo] El expediente dedicado a Hidra de Lerna (clasificación de peligrosidad: Alta) aborda en esta etapa la vigilancia continua mediante redes de telemetría y contención preventiva. Caracterizada por presentar múltiples cabezas regenerativas y aliento tóxico, esta entidad ha sido vinculada de forma recurrente con pantanos sulfurosos del Peloponeso. El presente registro documenta los avances obtenidos durante el ciclo anual 2026 para consolidar su ficha técnica dentro del Bestiario.', 'Durante la campaña de investigación correspondiente al año 2026, el equipo asignado al seguimiento de Hidra de Lerna centró sus esfuerzos en la vigilancia continua mediante redes de telemetría y contención preventiva. Las referencias documentales recolectadas en pantanos sulfurosos del Peloponeso permitieron contrastar relatos históricos previos con nuevos indicios verificados en terreno, destacando episodios de actividad estacional relacionados con su múltiples cabezas regenerativas y aliento tóxico. Cada hallazgo fue auditado y fechado el 2026-01-01 para preservar la trazabilidad evolutiva del caso.', 'Desde el punto de vista descriptivo (revisión 2026), Hidra de Lerna exhibe como rasgo diagnóstico principal múltiples cabezas regenerativas y aliento tóxico. Su nivel de amenaza (Alta) exige mantener distancia de seguridad en las inmediaciones de pantanos sulfurosos del Peloponeso, especialmente cuando las condiciones ambientales favorecen su desplazamiento. Las mediciones de la fase ''Protocolo Actual de Monitoreo'' confirman patrones de comportamiento consistentes con las observaciones acumuladas desde el inicio del archivo.', 'Síntesis 2026 de Hidra de Lerna: peligro Alta, hábitat principal en pantanos sulfurosos del Peloponeso y rasgo clave ''múltiples cabezas regenerativas y aliento tóxico''. Registro 5/5 correspondiente a la fase ''Protocolo Actual de Monitoreo'', validado para consulta histórica y comparativa.'),
(1, '2022-01-01 00:00:00', NULL, 1, 'aprobado', 2, 'bestiario_seed/beast_02', '[Edición 2022 - Revisión Historiográfica Inicial] El expediente dedicado a Quimera (clasificación de peligrosidad: Alta) aborda en esta etapa la recopilación de crónicas antiguas y manuscritos regionales. Caracterizada por presentar fisiología híbrida leonina, caprina y ofídica con emisión ígnea, esta entidad ha sido vinculada de forma recurrente con fisuras volcánicas de Licia. El presente registro documenta los avances obtenidos durante el ciclo anual 2022 para consolidar su ficha técnica dentro del Bestiario.', 'Durante la campaña de investigación correspondiente al año 2022, el equipo asignado al seguimiento de Quimera centró sus esfuerzos en la recopilación de crónicas antiguas y manuscritos regionales. Las referencias documentales recolectadas en fisuras volcánicas de Licia permitieron contrastar relatos históricos previos con nuevos indicios verificados en terreno, destacando episodios de actividad estacional relacionados con su fisiología híbrida leonina, caprina y ofídica con emisión ígnea. Cada hallazgo fue auditado y fechado el 2022-01-01 para preservar la trazabilidad evolutiva del caso.', 'Desde el punto de vista descriptivo (revisión 2022), Quimera exhibe como rasgo diagnóstico principal fisiología híbrida leonina, caprina y ofídica con emisión ígnea. Su nivel de amenaza (Alta) exige mantener distancia de seguridad en las inmediaciones de fisuras volcánicas de Licia, especialmente cuando las condiciones ambientales favorecen su desplazamiento. Las mediciones de la fase ''Revisión Historiográfica Inicial'' confirman patrones de comportamiento consistentes con las observaciones acumuladas desde el inicio del archivo.', 'Síntesis 2022 de Quimera: peligro Alta, hábitat principal en fisuras volcánicas de Licia y rasgo clave ''fisiología híbrida leonina, caprina y ofídica con emisión ígnea''. Registro 1/5 correspondiente a la fase ''Revisión Historiográfica Inicial'', validado para consulta histórica y comparativa.'),
