INSERT INTO `registro` (`nroRegistro`, `fechaAprobacion`, `fechaBaja`, `idUsuario`, `estado`, `idBestia`, `main_picture`, `introduccion`, `historia`, `descripcion`, `resumen`) VALUES
(1, '2022-01-01 00:00:00', NULL, 1, 'aprobado', 41, 'bestiario_seed/beast_41', '[Edición 2022 - Revisión Historiográfica Inicial] El expediente dedicado a Vampiro (clasificación de peligrosidad: Alta) aborda en esta etapa la recopilación de crónicas antiguas y manuscritos regionales. Caracterizada por presentar depredador hematófago fotofóbico de longevidad extrema, esta entidad ha sido vinculada de forma recurrente con pasos montañosos de Transilvania. El presente registro documenta los avances obtenidos durante el ciclo anual 2022 para consolidar su ficha técnica dentro del Bestiario.', 'Durante la campaña de investigación correspondiente al año 2022, el equipo asignado al seguimiento de Vampiro centró sus esfuerzos en la recopilación de crónicas antiguas y manuscritos regionales. Las referencias documentales recolectadas en pasos montañosos de Transilvania permitieron contrastar relatos históricos previos con nuevos indicios verificados en terreno, destacando episodios de actividad estacional relacionados con su depredador hematófago fotofóbico de longevidad extrema. Cada hallazgo fue auditado y fechado el 2022-01-01 para preservar la trazabilidad evolutiva del caso.', 'Desde el punto de vista descriptivo (revisión 2022), Vampiro exhibe como rasgo diagnóstico principal depredador hematófago fotofóbico de longevidad extrema. Su nivel de amenaza (Alta) exige mantener distancia de seguridad en las inmediaciones de pasos montañosos de Transilvania, especialmente cuando las condiciones ambientales favorecen su desplazamiento. Las mediciones de la fase ''Revisión Historiográfica Inicial'' confirman patrones de comportamiento consistentes con las observaciones acumuladas desde el inicio del archivo.', 'Síntesis 2022 de Vampiro: peligro Alta, hábitat principal en pasos montañosos de Transilvania y rasgo clave ''depredador hematófago fotofóbico de longevidad extrema''. Registro 1/5 correspondiente a la fase ''Revisión Historiográfica Inicial'', validado para consulta histórica y comparativa.'),
